function createGrid(x, y, w, cellCount) {
	let cellW = w / cellCount;
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let cellX = j * cellW + cellW / 2 + x - (w / 2);
			let cellY = i * cellW + cellW / 2 + y - (w / 2);
			shapes.push({ x: cellX, y: cellY, w: cellW });
		}
	}
}

function drawRandomShape(x, y, w) {
	let a = int(random(4)) * (TAU / 4);
	let ptnType = ceil(random(3));
	let num = ceil(random(5));
	shuffle(palette, true);
	let clr1 = palette[0];
	let clr2 = palette[1];
	push();
	translate(x, y);
	rotate(a);
	if (ptnType == 1) {
		drawStripe(0, 0, w, num, clr1, clr2);
	} else if (ptnType == 2) {
		drawCheckered(0, 0, w, num + 1, clr1, clr2);
	} else if (ptnType == 3) {
		drawPolkaDots(0, 0, w, num + 1, clr1, clr2);
	}
	noFill();
	stroke('#000');
	strokeWeight(width / 200);
	square(0, 0, w);
	pop();
}

function drawStripe(x, y, w, num, clr1, clr2) {
	let thickness = ((w * sqrt(2)) / num) * 0.5;
	push();
	translate(x - (w / 2), y - (w / 2));
	noStroke();
	fill(clr1);
	square(w / 2, w / 2, w);
	ctx.clip();
	strokeWeight(thickness);
	strokeCap(PROJECT);
	stroke(clr2);
	for (let i = 0; i < num; i++) {
		let x = map(i, 0, num, 0, w * 2) + (w / num) / 2;
		line(x, 0, x - w, 0 + w);
	}
	pop();
}

function drawCheckered(x, y, w, num, clr1, clr2) {
	let cellW = w / num;
	push();
	translate(x - (w / 2), y - (w / 2));
	noStroke();
	fill(clr1);
	square(w / 2, w / 2, w);
	for (let i = 0; i < num; i++) {
		for (let j = 0; j < num; j++) {
			let cellX = j * cellW;
			let cellY = i * cellW;
			if ((i + j) % 2 == 0) {
				fill(clr2);
				square(cellX + cellW / 2, cellY + cellW / 2, cellW);
			}
		}
	}
	pop();
}

function drawPolkaDots(x, y, w, num, clr1, clr2) {
	let cellW = w / num;
	push();
	translate(x - (w / 2), y - (w / 2));
	noStroke();
	fill(clr1);
	square(w / 2, w / 2, w);
	for (let i = 0; i < num; i++) {
		for (let j = 0; j < num; j++) {
			let cellX = j * cellW;
			let cellY = i * cellW;
			fill(clr2);
			circle(cellX + cellW / 2, cellY + cellW / 2, cellW * 0.5);
		}
	}
	pop();
}


